-- Disposable development project only. All generated fixtures are rolled back.
begin;
select set_config('test.source_editor',gen_random_uuid()::text,true),set_config('test.source_writer',gen_random_uuid()::text,true),set_config('test.source_regular',gen_random_uuid()::text,true);
insert into auth.users(id) select current_setting(k)::uuid from unnest(array['test.source_editor','test.source_writer','test.source_regular']) as k;
insert into public.admin_profiles(user_id,role) values (current_setting('test.source_editor')::uuid,'editor'),(current_setting('test.source_writer')::uuid,'writer');
select set_config('request.jwt.claim.sub',current_setting('test.source_editor'),true);
set local role authenticated;
insert into public.official_sources(name,organization,url,verified_on,review_due,is_verified) values ('source-test-version','test','https://example.invalid/source',(now() at time zone 'Asia/Riyadh')::date,(now() at time zone 'Asia/Riyadh')::date + 1,true);
update public.official_sources set name='source-test-updated' where name='source-test-version';
do $$ begin if (select count(*) from public.source_revisions where snapshot->>'name' in ('source-test-version','source-test-updated')) <> 2 then raise exception 'missing source revisions'; end if; if (select count(*) from public.source_revisions where snapshot->>'name' in ('source-test-version','source-test-updated') and changed_by=auth.uid()) <> 2 then raise exception 'wrong editor'; end if; end $$;
reset role;
select set_config('request.jwt.claim.sub',current_setting('test.source_regular'),true);
set local role authenticated;
do $$ begin if (select count(*) from public.source_revisions) <> 0 then raise exception 'regular user can read revisions'; end if; end $$;
reset role;
select set_config('request.jwt.claim.sub',current_setting('test.source_writer'),true);
set local role authenticated;
do $$ begin if (select count(*) from public.source_revisions where snapshot->>'name'='source-test-updated') <> 1 then raise exception 'writer cannot read history'; end if; update public.official_sources set name='bad-write' where name='source-test-updated'; if found then raise exception 'writer can modify source'; end if; end $$;
reset role;
select set_config('request.jwt.claim.sub',current_setting('test.source_editor'),true);
set local role authenticated;
update public.official_sources set name='source-test-version',is_verified=false,verified_on=null,review_due=null where name='source-test-updated';
do $$ begin if (select count(*) from public.source_revisions where snapshot->>'name'='source-test-version') <> 2 then raise exception 'restore not recorded'; end if; end $$;
reset role;
set local role anon;
do $$ begin if (select count(*) from public.official_sources where name='source-test-version') <> 0 then raise exception 'unverified source publicly visible'; end if; begin perform count(*) from public.source_revisions; raise exception 'anon read revisions'; exception when insufficient_privilege then null; end; end $$;
reset role;
select 'source revision RLS smoke tests passed; fixtures rolled back' as result;
rollback;
